		\approx_{\delta_S}& \Big ( \tilde{M}^{W,\tilde{u}}_a \Big)_{\alice \alice'\alice''} \cdot \Big ( \sum_g (\hat{S}^W_g)_{\alice \alice'} \otimes  (\hat{M}^{(\Point,W),u}_{g(u)})_{\bob \alice''} \Big) \label{eq:qld-pulling-1} \\
